options.afterRender:
var el=context.element||context.grafana?.element;if(!el)return;var root=el.querySelector('#h3-src-root');if(!root)return;var allRows=[];try{allRows=JSON.parse(root.dataset.rows||'[]')}catch(e){allRows=[]}var tableEl=root.querySelector('#h3-src-table'),pageEl=root.querySelector('#h3-src-pagination');var state={page:1,pageSize:10,busy:{}};
function escapeHtml(v){return String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;')}
function icon(n,s){s=s||22;var p={layers:'<path d=\"M12 3 3.5 7.5 12 12l8.5-4.5L12 3Z\"/><path d=\"m5 11 7 3.7 7-3.7\"/><path d=\"m5 15 7 3.7 7-3.7\"/>',server:'<rect x=\"4\" y=\"4\" width=\"16\" height=\"6\" rx=\"2\"/><rect x=\"4\" y=\"14\" width=\"16\" height=\"6\" rx=\"2\"/><circle cx=\"8\" cy=\"7\" r=\".8\" fill=\"currentColor\" stroke=\"none\"/><circle cx=\"8\" cy=\"17\" r=\".8\" fill=\"currentColor\" stroke=\"none\"/>',db:'<ellipse cx=\"12\" cy=\"5.5\" rx=\"7.5\" ry=\"3\"/><path d=\"M4.5 5.5v6c0 1.7 3.4 3 7.5 3s7.5-1.3 7.5-3v-6\"/><path d=\"M4.5 11.5v6c0 1.7 3.4 3 7.5 3s7.5-1.3 7.5-3v-6\"/>',dboff:'<ellipse cx=\"12\" cy=\"5.5\" rx=\"7.5\" ry=\"3\"/><path d=\"M4.5 5.5v6c0 1.7 3.4 3 7.5 3 1.1 0 2.2-.1 3.2-.4M19.5 11.5v-6\"/><path d=\"m5 5 14 14\"/>',pause:'<path d=\"M8 6v12M16 6v12\" stroke-width=\"2.5\"/>',play:'<path d=\"m8 5 10 7-10 7Z\" fill=\"none\"/>',trash:'<path d=\"M4.5 7.5h15M9 4h6M7 7.5l.8 12h8.4l.8-12M10 11v5M14 11v5\"/>',check:'<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"m8 12 2.5 2.5L16 9\"/>',warning:'<path d=\"m12 3 9 16H3L12 3Z\"/><path d=\"M12 9v4M12 16h.01\"/>',error:'<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 8v5M12 16h.01\"/>',info:'<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 10v6M12 7h.01\"/>'};return '<svg width=\"'+s+'\" height=\"'+s+'\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">'+(p[n]||p.info)+'</svg>'}
function showMessage(type,message){var c={success:{bg:'#dcfce7',color:'#166534',border:'#86efac',i:'check'},error:{bg:'#fee2e2',color:'#991b1b',border:'#fca5a5',i:'error'},info:{bg:'#dbeafe',color:'#1d4ed8',border:'#93c5fd',i:'info'}}[type]||{bg:'#dbeafe',color:'#1d4ed8',border:'#93c5fd',i:'info'};var m=root.querySelector('#h3-src-message');if(!m){m=document.createElement('div');m.id='h3-src-message';m.style.marginBottom='12px';root.insertBefore(m,root.firstChild)}m.innerHTML='<div style=\"padding:10px 14px;border-radius:10px;background:'+c.bg+';color:'+c.color+';border:1px solid '+c.border+';font-size:13px;font-weight:600;display:flex;align-items:center;gap:8px;\">'+icon(c.i,17)+'<span>'+escapeHtml(message)+'</span></div>';clearTimeout(state.messageTimer);state.messageTimer=setTimeout(function(){m.innerHTML=''},5000)}
function runQuery(sql,refId){return fetch('/api/ds/query',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},credentials:'same-origin',body:JSON.stringify({from:'now-5m',to:'now',queries:[{refId:refId||'ACTION',datasource:{type:'postgres',uid:'postgres-hypertension'},rawSql:sql,format:'table',rawQuery:true}]})}).then(function(r){if(!r.ok)throw new Error('Grafana query failed ('+r.status+')');return r.json()})}
function getResult(body,refId){try{var f=body.results[(refId||'ACTION')].frames[0];if(f&&f.data&&f.data.values&&f.data.values[0])return f.data.values[0][0]}catch(e){console.error('Unable to parse query result:',e)}return null}
function parseFunctionResult(body,refId){var result=getResult(body,refId);if(typeof result==='string'){try{result=JSON.parse(result)}catch(e){throw new Error('Invalid response returned by delete function')}}if(!result)throw new Error('No response returned by delete function');return result}
function closeModal(){var m=document.getElementById('h3-purge-modal');if(m)m.remove()}
function createModal(html){var o=document.getElementById('h3-purge-modal');if(o)o.remove();var m=document.createElement('div');m.id='h3-purge-modal';m.style.position='fixed';m.style.inset='0';m.style.zIndex='99999';m.style.background='rgba(17,24,39,.28)';m.style.display='flex';m.style.alignItems='center';m.style.justifyContent='center';m.style.padding='24px';m.innerHTML=html;document.body.appendChild(m);m.onclick=function(e){if(e.target===m)closeModal()};return m}
function updatePause(sourceKey,currentPaused){if(state.busy[sourceKey])return;state.busy[sourceKey]=true;renderTable();var key=String(sourceKey).replace(/'/g,"''");var sql="UPDATE heart360tk_reporting.import_source_control SET is_paused="+(!currentPaused)+",paused_changed_at=NOW() WHERE source_key='"+key+"';";runQuery(sql,'PAUSE').then(function(){var row=allRows.find(function(r){return r.source_key===sourceKey});if(row){row.is_paused=!currentPaused;row.paused_changed_at=new Date().toISOString()}showMessage('success',!currentPaused?'Importing paused for '+sourceKey:'Importing resumed for '+sourceKey)}).catch(function(e){showMessage('error',e.message||'Unable to update import control')}).finally(function(){delete state.busy[sourceKey];renderTable()})}
function purgeEverything(){
if(state.purging)return;
var loadedKeys=allRows.filter(function(r){return r.data_status==='data_loaded'}).map(function(r){return r.source_key});
if(!loadedKeys.length){showMessage('info','No leaf nodes with data to purge.');return}
var count=loadedKeys.length;
var nodeList=loadedKeys.map(function(k){return '<div style=\"display:flex;align-items:center;gap:10px;margin-top:10px;color:#333;font-size:16px;\">'+icon('server',19)+'<span>'+escapeHtml(k)+'</span></div>'}).join('');
var m=createModal('<div style=\"width:min(680px,calc(100vw - 48px));background:#fff;border-radius:18px;padding:28px 34px;color:#111827;box-shadow:0 24px 70px rgba(0,0,0,.18);font-family:Inter,system-ui,sans-serif;\">'+
'<div style=\"display:flex;align-items:flex-start;gap:16px;margin-bottom:20px;\">'+
'<div style=\"color:#a12828;padding-top:2px;\">'+icon('trash',31)+'</div>'+
'<div><div style=\"font-size:26px;font-weight:700;line-height:1.2;\">Purge all leaf node data?</div>'+
'<div style=\"font-size:17px;line-height:1.4;color:#555;margin-top:6px;\">This will remove data for all '+count+' loaded leaf node'+(count===1?'':'s')+'. The hierarchy will also be cleaned up where possible.</div></div></div>'+
'<div style=\"background:#f8f8f8;border:1px solid #e5e7eb;border-radius:14px;padding:14px 18px;margin-bottom:22px;max-height:240px;overflow-y:auto;\">'+
'<div style=\"font-size:16px;font-weight:700;color:#444;\">Leaf nodes to purge</div>'+nodeList+'</div>'+
'<div style=\"display:flex;justify-content:flex-end;gap:12px;\">'+
'<button id=\"h3-purge-cancel\" style=\"padding:11px 25px;border:1px solid #d3d3d3;border-radius:12px;background:#fff;color:#111827;font-size:17px;font-weight:600;cursor:pointer;\">Cancel</button>'+
'<button id=\"h3-purge-confirm\" style=\"padding:11px 25px;border:1px solid #f87171;border-radius:12px;background:#fff;color:#9f2d2d;font-size:17px;font-weight:600;cursor:pointer;\">Yes, purge everything</button>'+
'</div></div>');
m.querySelector('#h3-purge-cancel').onclick=closeModal;
m.querySelector('#h3-purge-confirm').onclick=function(){
closeModal();
state.purging=true;
loadedKeys.forEach(function(k){state.busy[k]=true});
renderTable();
showMessage('info','Purging all '+count+' leaf node'+(count===1?'':'s')+'...');
var keys=loadedKeys.map(function(k){return String(k).replace(/'/g,"''")});
var arraySql="ARRAY["+keys.map(function(k){return "'"+k+"'"}).join(',')+"]::text[]";
var sql="SELECT heart360tk_reporting.delete_leaf_node_data("+arraySql+",TRUE) AS result;";
runQuery(sql,'PURGE_ALL').then(function(body){
var result=parseFunctionResult(body,'PURGE_ALL');
if(result.success!==true||(result.failed_count&&result.failed_count>0))throw new Error(result.message||'Unable to purge data');
allRows.forEach(function(r){if(r.data_status==='data_loaded'){r.data_status='no_data';r.last_purged_at=new Date().toISOString()}});
showMessage('success',result.message||'All leaf node data purged successfully');
}).catch(function(e){
showMessage('error',e.message||'Unable to purge data');
}).finally(function(){
state.busy={};
state.purging=false;
renderTable();
});
};
}
function pageRows(){
var start=(state.page-1)*state.pageSize;
return allRows.slice(start,start+state.pageSize);
}
function renderPagination(){
var total=allRows.length,totalPages=Math.max(1,Math.ceil(total/state.pageSize));
if(state.page>totalPages)state.page=totalPages;
if(!total){pageEl.innerHTML='';return}
var start=(state.page-1)*state.pageSize+1,end=Math.min(state.page*state.pageSize,total);
var h='<div style=\"display:flex;justify-content:space-between;align-items:center;gap:16px;width:100%;\">'+
'<span style=\"font-size:13px;color:#6b7280;\">Showing '+start+'–'+end+' of '+total+' results</span>';
if(totalPages>1){
 h+='<div style=\"display:flex;gap:6px;align-items:center;\">'+
 '<button id=\"h3-prev\" style=\"min-width:34px;padding:6px 9px;border:1px solid #d5d9df;border-radius:7px;background:#fff;color:#374151;cursor:pointer;\">‹</button>';
 for(var i=1;i<=totalPages;i++){
  h+='<button data-page=\"'+i+'\" style=\"min-width:32px;padding:6px 9px;border:1px solid '+(i===state.page?'#93b4e8':'#d5d9df')+';border-radius:7px;background:'+(i===state.page?'#eef5ff':'#fff')+';color:'+(i===state.page?'#1d4f91':'#374151')+';font-weight:'+(i===state.page?'700':'500')+';cursor:pointer;\">'+i+'</button>';
 }
 h+='<button id=\"h3-next\" style=\"min-width:34px;padding:6px 9px;border:1px solid #d5d9df;border-radius:7px;background:#fff;color:#374151;cursor:pointer;\">›</button></div>';
}
h+='</div>';
pageEl.innerHTML=h;
var p=pageEl.querySelector('#h3-prev'),n=pageEl.querySelector('#h3-next');
if(p)p.onclick=function(){if(state.page>1){state.page--;renderTable()}};
if(n)n.onclick=function(){if(state.page<totalPages){state.page++;renderTable()}};
Array.prototype.forEach.call(pageEl.querySelectorAll('[data-page]'),function(b){b.onclick=function(){state.page=parseInt(b.dataset.page,10);renderTable()}})
}

function renderTable(){
var loadedCount=allRows.filter(function(r){return r.data_status==='data_loaded'}).length,
 totalCount=allRows.length,
 rows=pageRows(),
 html='<div style=\"width:100%;overflow-x:auto;border:1px solid #e5e7eb;border-radius:14px;background:#fff;box-shadow:0 1px 2px rgba(0,0,0,.03);\"><table style=\"width:100%;min-width:900px;border-collapse:collapse;font-size:14px;table-layout:fixed;\"><thead><tr style=\"border-bottom:1px solid #e5e7eb;height:54px;background:#fafbfc;\">';

html+='<th style=\"width:30%;text-align:left;padding:0 24px;color:#596273;font-weight:700;font-size:14px;\">Leaf Node</th>'+
'<th style=\"width:20%;text-align:left;padding:0 24px;color:#596273;font-weight:700;font-size:14px;\">Data Status</th>'+
'<th style=\"width:25%;text-align:left;padding:0 24px;color:#596273;font-weight:700;font-size:14px;\">Import Control</th>'+
'<th style=\"width:25%;text-align:left;padding:0 24px;color:#596273;font-weight:700;font-size:14px;\">Mapping Review</th></tr></thead><tbody>';

rows.forEach(function(r){
var loaded=r.data_status==='data_loaded',
 paused=r.is_paused===true,
 busy=state.busy[r.source_key]===true,
 review=r.review_note||'',
 reviewHtml=review?'<div style=\"display:flex;align-items:flex-start;gap:9px;color:#5b6472;font-size:14px;line-height:1.35;\">'+icon(/no central mapping|review required/i.test(review)?'error':'warning',20)+'<span>'+escapeHtml(review)+'</span></div>':'<div style=\"display:flex;align-items:center;gap:9px;color:#5b6472;font-size:14px;\">'+icon('check',20)+'<span>Mapped</span></div>';

html+='<tr style=\"border-bottom:1px solid #edf0f3;height:92px;transition:background .15s;\">'+
'<td style=\"padding:0 24px;font-size:16px;font-weight:700;color:#1f2937;white-space:nowrap;\"><span style=\"display:inline-flex;vertical-align:middle;margin-right:10px;color:#667085;\">'+icon('server',20)+'</span>'+escapeHtml(r.source_key)+'</td>'+
'<td style=\"padding:0 24px;\"><span style=\"display:inline-flex;align-items:center;gap:8px;padding:8px 13px;border-radius:999px;background:'+(loaded?'#e1f6df':'#f3f4f6')+';color:'+(loaded?'#17741c':'#667085')+';font-size:14px;font-weight:700;white-space:nowrap;\">'+icon(loaded?'db':'dboff',18)+' '+(loaded?'Data loaded':'No data')+'</span></td>'+
'<td style=\"padding:0 24px;\"><button data-pause=\"'+escapeHtml(r.source_key)+'\" '+(busy?'disabled':'')+' style=\"display:inline-flex;align-items:center;gap:9px;padding:10px 16px;border:1px solid #d7dce2;border-radius:9px;background:#fff;color:#1f2937;font-size:14px;font-weight:600;cursor:'+(busy?'wait':'pointer')+';\">'+icon(busy?'info':(paused?'play':'pause'),18)+(busy?'Processing...':(paused?'Resume importing':'Pause importing'))+'</button></td>'+
'<td style=\"padding:0 24px;\">'+reviewHtml+'</td></tr>';
});
html+='</tbody></table></div>';
tableEl.innerHTML=html;

Array.prototype.forEach.call(tableEl.querySelectorAll('[data-pause]'),function(b){
b.onclick=function(){
var k=b.dataset.pause,row=allRows.find(function(r){return r.source_key===k});
if(row)updatePause(k,row.is_paused===true)
}
});

var loadedMetric=root.querySelector('#h3-loaded-count');
if(loadedMetric)loadedMetric.textContent=loadedCount+' / '+totalCount;
var purgeButton=root.querySelector('#h3-purge-everything');
if(purgeButton){
 purgeButton.disabled=loadedCount===0||state.purging;
 purgeButton.style.color=loadedCount>0?'#9f2d2d':'#9aa2af';
 purgeButton.style.borderColor=loadedCount>0?'#f87171':'#e5e7eb';
 purgeButton.style.cursor=loadedCount>0&&!state.purging?'pointer':'not-allowed';
}
renderPagination();
}

var purgeBtn=root.querySelector('#h3-purge-everything');
if(purgeBtn)purgeBtn.onclick=function(){purgeEverything()};
renderTable();

list.definition:
SELECT CASE WHEN (u.is_admin OR EXISTS (
  SELECT 1 FROM grafana_schema.team_member tm
  JOIN grafana_schema.team t ON tm.team_id = t.id
  WHERE tm.user_id = u.id AND t.name LIKE '%\_ALL' ESCAPE '\'
)) THEN 1 ELSE 0 END
FROM grafana_schema."user" u WHERE u.id = ${__user.id}

